#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char **data;
    int size;
    int capacity;
} StringArray;

void sa_init(StringArray *sa) {
    sa->capacity = 16;
    sa->size = 0;
    sa->data = (char **)malloc(sizeof(char *) * sa->capacity);
}

void sa_push(StringArray *sa, char *str) {
    if (sa->size == sa->capacity) {
        sa->capacity *= 2;
        sa->data = (char **)realloc(sa->data, sizeof(char *) * sa->capacity);
    }
    sa->data[sa->size++] = str;
}

void sa_free(StringArray *sa) {
    for (int i = 0; i < sa->size; i++) {
        free(sa->data[i]);
    }
    free(sa->data);
    sa->size = 0;
    sa->capacity = 0;
}

int isValidInteger(const char *s, int len) {
    // Valid integer rules:
    // - single '0' is valid
    // - no leading zeros if length > 1
    if (len == 1) {
        return 1; // single digit always valid
    }
    if (s[0] == '0') return 0;
    return 1;
}

int isValidDecimal(const char *s, int len, int dotPos) {
    // dotPos is index of decimal point in the string (0-based)
    // s is the string without dot, so we build the decimal string by inserting dot at dotPos
    // Rules:
    // - integer part (before dot) must be valid integer (no leading zeros unless single '0')
    // - fractional part (after dot) must not end with zero (no trailing zeros)
    // - fractional part length >= 1
    // - no trailing zeros in fractional part
    // - fractional part cannot be empty
    // - no leading zeros in integer part except single zero allowed

    // integer part length = dotPos
    // fractional part length = len - dotPos

    // integer part check
    if (!isValidInteger(s, dotPos)) return 0;

    // fractional part check
    int fracLen = len - dotPos;
    if (fracLen < 1) return 0;

    // fractional part cannot end with '0'
    if (s[len - 1] == '0') return 0;

    return 1;
}

StringArray generateNumbers(const char *s, int len) {
    // Generate all valid numbers from s[0..len-1]
    // Return array of strings (malloced)
    StringArray res;
    sa_init(&res);

    // Try integer only (no dot)
    if (isValidInteger(s, len)) {
        char *num = (char *)malloc(len + 1);
        memcpy(num, s, len);
        num[len] = 0;
        sa_push(&res, num);
    }

    // Try decimal points at every possible position (1..len-1)
    for (int dot = 1; dot < len; dot++) {
        if (isValidDecimal(s, len, dot)) {
            // build string with dot inserted at dot
            // length = len + 1
            char *num = (char *)malloc(len + 2);
            memcpy(num, s, dot);
            num[dot] = '.';
            memcpy(num + dot + 1, s + dot, len - dot);
            num[len + 1] = 0;
            sa_push(&res, num);
        }
    }
    return res;
}

char **ambiguousCoordinates(char * s, int* returnSize){
    // s format: "(digits)"
    // extract digits inside parentheses
    int n = (int)strlen(s);
    int len = n - 2;
    char *digits = (char *)malloc(len + 1);
    memcpy(digits, s + 1, len);
    digits[len] = 0;

    StringArray ans;
    sa_init(&ans);

    // split digits into two parts: left and right
    // left length: i, right length: len - i, i from 1 to len-1
    for (int i = 1; i < len; i++) {
        StringArray leftNums = generateNumbers(digits, i);
        StringArray rightNums = generateNumbers(digits + i, len - i);

        for (int li = 0; li < leftNums.size; li++) {
            for (int ri = 0; ri < rightNums.size; ri++) {
                // format: "(left, right)"
                int leftLen = (int)strlen(leftNums.data[li]);
                int rightLen = (int)strlen(rightNums.data[ri]);
                int totalLen = leftLen + rightLen + 4; // 4 for '(', ',', ' ', ')'
                char *coord = (char *)malloc(totalLen + 1);
                sprintf(coord, "(%s, %s)", leftNums.data[li], rightNums.data[ri]);
                sa_push(&ans, coord);
            }
        }
        sa_free(&leftNums);
        sa_free(&rightNums);
    }

    free(digits);
    *returnSize = ans.size;
    return ans.data;
}

